insert into public.page_content_translation (content_id, locale, value) select pc.id, 'id', 'Jangkar Coffee Industry berdiri di Palembang sebagai industri kopi, bukan kedai yang kebetulan menjual kopi. Yang dikerjakan bukan sekadar menyeduh: biji dibeli dari kebun di Semendo, disangrai di roastery Sako, lalu berpindah ke gerai, ke armada keliling, dan ke kemasan yang bisa dibawa pulang.
insert into public.page_content_translation (content_id, locale, value) select pc.id, 'en', 'Jangkar Coffee Industry works out of Palembang as a coffee industry, not a shop that happens to sell coffee. Brewing is only the last part of it: beans are bought from farms in Semendo, roasted at the Sako roastery, then move on to the outlet, to the mobile fleet, and into packaging you can carry home.
